script:
let topPacketFilterValue = 5; // stores filter number

frappe.after_ajax(() => {
  const btn = root_element.querySelector("#tsp-filter-btn");
  if (btn) {
    btn.addEventListener("click", openTopPacketsFilter);
  }

  renderTopServicePackets();
});

function openTopPacketsFilter() {
  frappe.prompt(
    [
      {
        fieldname: "min_count",
        label: "Show Top N Packets",
        fieldtype: "Int",
        default: topPacketFilterValue,
      },
    ],
    (values) => {
      topPacketFilterValue = values.min_count;
      renderTopServicePackets(); // reload with filter
    },
    "Filter Top Service Packets",
    "Apply"
  );
}

function renderTopServicePackets() {
  const container = root_element.querySelector("#top-service-packets");
  if (!container) return;

  container.querySelector(".tsp-empty").innerHTML = "Loading...";

  frappe.call({
    method:
      "service_warehouse.service_warehouse.dashboard_chart_source.service_packets.get_top_service_packets_for_tenant",
    args: {
      limit: topPacketFilterValue, // send filter to backend
    },
    callback: function (response) {
      const list = response.message || [];

      container.querySelectorAll(".tsp-item").forEach((el) => el.remove());

      if (list.length === 0) {
        container.querySelector(".tsp-empty").innerHTML =
          "No subscriptions found.";
        return;
      }

      container.querySelector(".tsp-empty").innerHTML = "";

      list.forEach((packet, index) => {
        const div = document.createElement("div");
        div.className = "tsp-item";

        const color = generatePacketColor(index);
        div.style.setProperty("--clr", color);

        const url = `/app/service-packet/${encodeURIComponent(
          packet.service_packet
        )}`;

        div.innerHTML = `
                    <a href="${url}">
                        <div class="tsp-name">${
                          packet.title || packet.service_packet
                        }</div>
                    </a>
                    <div class="tsp-count">${packet.total} subscriptions</div>
                `;

        container.appendChild(div);
      });
    },
  });
}

function generatePacketColor(index) {
  const colors = ["#3b82f6", "#10b981", "#f59e0b", "#ef4444", "#8b5cf6"];
  return colors[index] || "#6b7280";
}

