function renderPacketVersions() {
    frappe.call({
        method: "service_warehouse.service_warehouse.dashboard_chart_source.service_packets.get_service_packet_versions",
        callback: function (response) {
            const packets = response.message || [];
            console.log(response)
            const container = root_element.querySelector("#packet-version-list");

            if (!container) return;
            container.innerHTML = "";

            if (packets.length === 0) {
                container.innerHTML = `<div class="pv-empty">No packets found.</div>`;
                return;
            }

            packets.forEach((packet) => {
                const wrapper = document.createElement("div");
                wrapper.className = "packet-card";

                wrapper.innerHTML = `
                    <div class="packet-header">
                        <div class="packet-title">${packet.packet_name}</div>
                        <div class="packet-count">${packet.versions.length} versions</div>
                    </div>

                    <div class="packet-version-list">
                        <ul>
                            ${packet.versions
                                .map(
                                    (ver) => `
                                <li>
                                    <div class="v-row">
                                        <span class="v-code">${ver.name}</span>
                                        <span class="v-date">v${ver.major}.${ver.minor}</span>
                                    </div>
                                </li>`
                                )
                                .join("")}
                        </ul>
                    </div>
                `;

                container.appendChild(wrapper);
            });
        }
    });
}

